contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the minimal sequence:
    // ensure this contract has enough ETH, call Deposit (via payable call), then assert recorded balance >= deposited amount
    function check_deposit(uint256 depositAmount) public {
        // precondition: this contract must have at least depositAmount to forward
        require(address(this).balance >= depositAmount);

        // perform the deposit into c by calling its payable Deposit (use low-level call to send value to Deposit())
        // but we must call the public Deposit function; using c.Deposit{value:...}() is allowed
        c.Deposit{value: depositAmount}();

        // read the public balances mapping for this contract's address
        uint256 recorded = c.balances(address(this));

        // On the original P this should hold: after depositing X, recorded balance >= X
        // On the mutant M (which subtracts instead of adding) this will fail for any depositAmount>0
        assert(recorded >= depositAmount);
    }

    // allow funding this test contract for the check
    receive() external payable {}
}

