pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (actor) and amounts for deposit and collect, and a third address to check balances at some key
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt, address checkKey) public {
        // Keep amounts reasonable but wide
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Ensure depositor has ETH to send
        vm.deal(depositor, depositAmt + 1);

        // Make the depositor perform a Deposit of depositAmt
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Optionally initialize MinSum low so Collect can proceed depending on balances
        // Only call SetMinSum before Initialized - reference and mutant both allow it
        c.SetMinSum(0);
        c.Initialized();

        // Now have depositor call Collect(collectAmt)
        // wrap to ensure call completes or reverts without failing the test run
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General invariant to assert (single assertTrue): In the correct contract, Deposit always increases balances[depositor] by depositAmt (so balances[depositor] >= depositAmt - collectAmt when collect succeeded or >=0 otherwise). We observe the contract only via its public getter balances(address).
        // We assert that balances of depositor (a public getter) is <= address(c).balance + type(uint256).max; however we must produce a predicate that holds for the correct contract for all inputs and is violated by the mutant for some inputs.
        // Simpler correct universal property: after a direct Deposit of depositAmt from depositor, the public getter balances(depositor) is at least depositAmt - collectAmt if Collect returned true and was allowed; but to be universal for all inputs regardless of ok, we assert that balances(checkKey) is not reduced by the act of Deposit+Collect below zero in the correct contract: specifically, in the reference balances(checkKey) is never greater than prior balances(checkKey) + depositAmt (i.e., Deposit cannot decrease other keys). The mutant's buggy Deposit subtracts and can reduce other keys causing balances(checkKey) to be less than before.

        // Read balance for checkKey before operations would be needed; but test must have single assert and only observe c now. To craft a universal property: In the correct contract, after a Deposit by depositor and an attempted Collect, the balances of any key cannot be negative and specifically cannot be less than 0. Since balances is uint256, that holds. But mutant can underflow (in solidity 0.8 underflow reverts) — however the mutant will cause balances to decrease which may make balances(checkKey) < balances(checkKey) of reference. We need a predicate readable now that holds for reference for all inputs and is violated by mutant for some.

        // We use the following observable property: The sum of address(c).balance and the public sum of all balances is consistent: in the reference, address(c).balance equals the sum of all balances stored (since contract holds deposited ETH and only pays out on Collect). However we cannot read the sum of all balances (no public getter for History length only individual mapping). So instead, pick a key equal to depositor: in the reference, after depositing depositAmt, balances(depositor) >= depositAmt - collectAmt (if collect succeeded) and always >= 0. The mutant that subtracts on Deposit can make balances(depositor) < depositAmt - collectAmt, violating that.

        // We therefore assert the universal property: balances(depositor) + collectAmt >= 0 and specifically that balances(depositor) + collectAmt >= 0 is tautological. To make it nontrivial and catch mutant: assert balances(depositor) + collectAmt >= depositAmt. In the reference, if collect succeeded it reduces by collectAmt so balances(depositor) >= depositAmt - collectAmt, rearranged gives balances(depositor) + collectAmt >= depositAmt. If collect failed, balances(depositor) >= depositAmt, so also balances(depositor) + collectAmt >= depositAmt. Thus for ALL inputs in the correct contract this holds. The mutant where Deposit subtracted may make balances(depositor) much smaller so the property can fail for some fuzzed inputs.

        // Single required assertion reading c's public getter
        assertTrue(c.balances(depositor) + collectAmt >= depositAmt);
    }
}

