pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (who will deposit and collect), amount deposited, some other address watcher
    function testFuzz_property(address depositor, uint256 depositAmt, address watcher) public {
        // Keep addresses non-zero and distinct to avoid trivial overlaps
        vm.assume(depositor != address(0));
        vm.assume(watcher != address(0));

        // Keep depositAmt reasonable (nonzero) and bounded to avoid overflows in the test env
        depositAmt = bound(depositAmt, 1, 1 ether);

        // Fund depositor so they can deposit
        vm.deal(depositor, depositAmt);

        // Record watcher's balance slot before any operations via public getter
        uint256 beforeWatcherBal = c.balances(watcher);

        // Perform Deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Now attempt Collect by depositor: collect entire deposited amount
        // Use try/catch to avoid test reverts; Collect may revert silently if conditions not met
        bool ok;
        try c.Collect(depositAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the roundtrip, in the correct contract, no other address's balances should have increased
        // (Deposits only affect msg.sender's balances; Collect only decreases balances[msg.sender] on success)
        // So watcher balance must be <= beforeWatcherBal. We assert the non-increase property.
        uint256 afterWatcherBal = c.balances(watcher);

        assertTrue(afterWatcherBal <= beforeWatcherBal);
    }
}

