contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: actor who will deposit/collect and an amount to deposit/collect
    function testFuzz_property(address actor, uint256 amt) public {
        // keep actor non-zero and amount reasonable to avoid overflow in test harness
        vm.assume(actor != address(0));
        amt = bound(amt, 1, 1 ether);

        // fund the actor so they can send Ether
        vm.deal(actor, amt + 1);

        // compute total stored balances before any actions by reading some sample addresses.
        // Since mapping keys are unbounded, we cannot enumerate; instead we rely on the fact that
        // initially all balances are zero and our sequence will only affect balances[actor].
        // The general rule we assert is: after a Deposit by actor, the total stored balances (here
        // represented by balances(actor)) is non-decreasing. This is valid because before any
        // interactions the only non-zero entries will be those we create.

        // read stored balance before
        uint256 before = c.balances(actor);

        // perform Deposit from actor of amt
        vm.prank(actor);
        c.Deposit{value: amt}();

        // After Deposit, reference must have balances[actor] >= before (Deposit increases);
        // mutant that subtracts may make it smaller. We assert the non-decreasing property.
        uint256 afterDeposit = c.balances(actor);
        assertTrue(afterDeposit >= before);

        // Now attempt Collect of some portion (use same amt to keep within available balance)
        // wrap in try/catch to observe whether Collect reverts; but we only need to observe balances
        // after Collect. Use actor to call Collect.
        vm.prank(actor);
        try c.Collect(amt) {
            // success
        } catch {
            // ignore revert; Collect may simply do nothing if preconditions fail
        }

        // Finally, the general invariant we enforce: total stored balances should never be
        // negative and specifically the balances[actor] after Deposit should not be less than before
        // the Deposit. This single assertTrue reads c and is satisfied by the reference for all inputs
        // but violated by the mutant for some inputs.
        uint256 finalBal = c.balances(actor);
        assertTrue(finalBal >= before);
    }
}

