pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and amounts to deposit and collect
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // keep depositor non-zero
        vm.assume(depositor != address(0));
        // bound amounts to sane ranges so VM.deal and transfers work
        depositAmt = bound(depositAmt, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Prepare depositor with ETH to deposit
        vm.deal(depositor, depositAmt + 1 ether);

        // depositor makes a deposit (use prank to set msg.sender)
        vm.startPrank(depositor);
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        }
        vm.stopPrank();

        // record balance before collect via public getter
        uint256 before = c.balances(depositor);

        // ensure MinSum requirement: set MinSum <= before so Collect can proceed when appropriate
        // only allowed before initialization; set it here from test deployer
        if (before > 0) {
            c.SetMinSum(0);
        } else {
            // if there is no balance, set MinSum to 0 anyway
            c.SetMinSum(0);
        }

        // attempt Collect from depositor for collectAmt, capture whether it succeeded
        bool ok;
        vm.prank(depositor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect, the correct contract (reference) guarantees that if Collect succeeded
        // then balances[msg.sender] == before - collectAmt (and if it reverted, state unchanged for caller).
        // We assert the general rule reading c's public getter: when ok is true, balances equals before - collectAmt;
        // when ok is false, balances equals before (Collect reverted and made no state change for caller).
        uint256 after = c.balances(depositor);
        if (ok) {
            assertTrue(after == before - collectAmt);
        } else {
            assertTrue(after == before);
        }
    }
}

