contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving the contract.
    // depositor: the address that will call Deposit on c (must be this contract's caller and therefore forwarded via msg.sender)
    // amount: the ether amount to send with Deposit
    // Note: we require this contract to hold at least `amount` wei before calling.
    function runTest(address depositor, uint256 amount) public payable {
        // Preconditions: this contract must hold the funds to forward
        require(address(this).balance >= amount, "insufficient balance for forwarding");

        // Ensure caller consistency: we need to have the Depositor be this contract calling c.
        // So depositor must equal address(this) for the intended scenario; enforce it.
        require(depositor == address(this), "depositor must be this contract");

        // Call Deposit on c, forwarding `amount` wei.
        c.Deposit{value: amount}();

        // Observe recorded balance via public getter
        uint256 recorded = c.balances(address(this));

        // The invariant that holds for the original contract: after depositing, stored balance >= deposited amount
        assert(recorded >= amount);
    }

    // Allow funding this contract so it can forward ether in tests
    receive() external payable {}
    fallback() external payable {}
}
